args.content:
export type Product = {
  id: number
  name: string
  price: number
  inventory: number
  available: boolean
  syncedAt?: string
}

let products: Product[] = [
  { id: 1, name: 'Laptop', price: 999, inventory: 120, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 300, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 85, available: true },
  { id: 4, name: 'Headphones', price: 199, inventory: 540, available: true },
  { id: 5, name: 'Watch', price: 299, inventory: 60, available: true },
]

export async function getAllProducts(): Promise<Product[]> {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return products
}

export async function syncCatalogFromERP(): Promise<number> {
  await new Promise((resolve) => setTimeout(resolve, 2000))

  const syncedAt = new Date().toISOString()
  products = products.map((p) => {
    const inventory = Math.max(0, p.inventory - 25)
    return {
      ...p,
      price: Math.max(1, Math.round(p.price * 0.9)),
      inventory,
      available: inventory > 0,
      syncedAt,
    }
  })

  return products.length
}

